import { withThemeByDataAttribute } from '@storybook/addon-themes';
import { setCustomElementsManifest, type Preview } from '@storybook/web-components-vite';
import customElements from '../custom-elements.json';
import { tokensCss } from '../src/shared/tokens/index.ts';
import '@product-theme';

// Generated by `pnpm run analyze`; it feeds the docs tables and controls.
setCustomElementsManifest(customElements);

// The catalog loads the same default tokens as consumers do (the published `tokens.css`), plus a
// page background and text color so stories are legible in both themes.
const style = document.createElement('style');
style.textContent = `${tokensCss}
body {
  background: var(--su3-sys-color-surface);
  color: var(--su3-sys-color-text);
  font-family: var(--su3-sys-typeface-sans);
}
.docs-story {
  background: var(--su3-sys-color-surface);
}`;
// Prepended, so the product theme (imported above) comes later in the cascade and wins at equal
// specificity, exactly as consumers load tokens.css first and a theme after it.
document.head.prepend(style);

const preview: Preview = {
  decorators: [
    withThemeByDataAttribute({
      themes: { light: 'light', dark: 'dark' },
      defaultTheme: 'light',
      attributeName: 'data-theme',
    }),
  ],
  parameters: {
    controls: { expanded: true },
    layout: 'centered',
    options: { storySort: { order: ['Foundation', '*'] } },
  },
  tags: ['autodocs'],
};

export default preview;
